select * from jsonb_populate_recordset(null::public.temples, $rtam$[{"id":"67f3b161-2356-48b4-a2d3-63c5cc7ef4ae","name":"Navdurga Temple, Madkai","deity":"Navdurga","sampradaya":"Shakta","significance":[],"country":"India","state":"Goa","district":"South Goa","town":"Madkai","latitude":15.41879,"longitude":73.94351,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Cumbarjua Canal River","river_distance_km":1.9,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:11.054915+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Goa temple to the goddess Navdurga, worshipped at Madkai and Kundaim after historical migrations of the community. The Madkai idol is known for its tilted head. The annual Zatra falls around November on Kartik Shukla Ashtami. A dispute from 2016 over replacing the idol caused a legal and social conflict over temple control.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Goa International Airport","nearest_airport_distance_km":12.6,"nearest_railway_station_name":"Verna railway station","nearest_railway_distance_km":7.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Navdurga Temple, Madkai), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"68090728-3863-4d93-bdb9-f568a802d684","name":"Devi Talab Mandir, Jalandhar","deity":"Durga, worshipped here as Tripurmalini (with Shiva as Bhishan)","sampradaya":"Shakta","significance":[],"country":"India","state":"Punjab","district":"Jalandhar","town":"Jalandhar","latitude":31.34361,"longitude":75.58306,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Bhangi River","river_distance_km":12.5,"best_season_notes":"Navratri and Durga Puja are the major festivals.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-26T20:05:50.919949+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Tradition holds this is a Shakti Peetha where a part of Sati fell, but sources disagree on which: the temple's own site says the right breast, another temple-listing site says the left. It is also not on every list of the 51 Peethas, so it is not tagged as one. The temple and its pond are often described as about 200 years old, an unverified figure.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":"The temple site lists a dharamshala, langar, a charitable hospital and toilets on the premises.","nearest_airport_name":"Adampur Air Force Station","nearest_airport_distance_km":19.7,"nearest_railway_station_name":"Jalandhar City Railway Station","nearest_railway_distance_km":1,"emergency_contact_notes":null,"sthala_purana_source":"Temple official site; Wikipedia (Devi Talab Mandir); Peetha attribution is traditional","architecture_style":null,"construction_century":null},{"id":"6848b317-edab-4148-a3b6-fc57178712e6","name":"Veerabhadra Swamy Temple, Mylapore","deity":"Veerabhadra (fierce form of Shiva)","sampradaya":"Shaiva","significance":[],"country":"India","state":"Tamil Nadu","district":"Chennai","town":"Mylapore","latitude":13.0325,"longitude":80.266,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Adyar River","river_distance_km":1.9,"best_season_notes":"Nov–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-08T06:51:40.218447+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"An old shrine near the Madhava Perumal Temple, notable as one of the few Chennai temples to house a murti of Adi Shankaracharya.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":11.5,"nearest_railway_station_name":"Thirumayilai railway station","nearest_railway_distance_km":0.4,"emergency_contact_notes":null,"sthala_purana_source":"Contributor-submitted local survey","architecture_style":null,"construction_century":null},{"id":"685bc7b7-69eb-4e3b-96d6-ab2548fc9079","name":"Varaha Cave Temple","deity":"Vishnu as Varaha","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Tamil Nadu","district":"Chengalpattu","town":"Venpurushanattam","latitude":12.6175,"longitude":80.19889,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":null,"river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:13:52.370722+00:00","updated_at":"2026-11-04T12:15:35.665826+00:00","sthala_purana":"A rock-cut cave temple at Mamallapuram, on the hill-top village north of the Shore Temple and rathas, dating from the late 7th century. Its main sculpture shows Vishnu as the boar Varaha lifting the earth goddess Bhudevi, alongside other carved figures. It is part of the UNESCO-listed Group of Monuments at Mahabalipuram.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":41.9,"nearest_railway_station_name":"Otivakkam railway station","nearest_railway_distance_km":24.3,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Varaha Cave Temple), summarised; location via OpenStreetMap","architecture_style":"Rock-cut cave temple","construction_century":7},{"id":"688faf74-ac5a-4b01-a553-1123db5e111f","name":"Nachna Hindu temples","deity":"Parvati (Parvati temple) and other shrines","sampradaya":null,"significance":[],"country":"India","state":"Madhya Pradesh","district":"Panna","town":"Nachne","latitude":24.39925,"longitude":80.44756,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Gudne River","river_distance_km":7.1,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:38.937899+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A group of mostly ruined stone temples in Panna district, among the earliest surviving in central India, dated variously to the Gupta era. The Parvati temple is best preserved, with a raised plinth, square sanctum and circumambulation passage. The carvings include some early Ramayana friezes.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Satna Airport","nearest_airport_distance_km":44.9,"nearest_railway_station_name":"Ghunwara railway station","nearest_railway_distance_km":34.8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Nachna Hindu temples), summarised; location via OpenStreetMap","architecture_style":"Gupta-era North Indian","construction_century":5},{"id":"68c63fe3-786f-458a-8f0a-beba4b6d9933","name":"Vadivudai Amman Temple, Tiruvottiyur","deity":"Vadivudai Amman / Tripurasundari (Devi)","sampradaya":"Shakta","significance":[],"country":"India","state":"Tamil Nadu","district":"Chennai","town":"Tiruvottiyur","latitude":13.1613,"longitude":80.3006,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Bay of Bengal","river_distance_km":1,"best_season_notes":"Nov–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-08T06:51:40.218447+00:00","updated_at":"2026-11-04T12:15:35.665826+00:00","sthala_purana":"Reported to be over 2,000 years old, paired with the neighbouring Aadhipureeswarar Shiva temple as one of the oldest continuously worshipped sites in Chennai's Tiruvottiyur suburb.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":23.6,"nearest_railway_station_name":"Tiruvottiyur railway station","nearest_railway_distance_km":0.5,"emergency_contact_notes":null,"sthala_purana_source":"Contributor-submitted local survey","architecture_style":null,"construction_century":null},{"id":"6909c906-1d47-4c9b-a09f-ff4f6088230d","name":"Pahari Mandir, Ranchi","deity":"Shiva (Shivalinga)","sampradaya":"Shaiva","significance":["Freedom struggle site"],"country":"India","state":"Jharkhand","district":"Ranchi","town":"Ranchi","latitude":23.375,"longitude":85.311,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Harmu River","river_distance_km":1.1,"best_season_notes":"Shravan (Jul–Aug) and Maha Shivaratri (Feb–Mar) draw the largest crowds, reportedly up to a lakh of devotees on Shivaratri.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T08:39:44.697229+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"This hilltop shrine sits on what was originally called Tiriburu hill; local tradition holds it earned the grim name \"Hanging Gallows\" under British rule, when freedom fighters were reportedly hanged there. After independence, freedom fighter K. C. Das is said to have hoisted the national flag at the site, and it is locally described as among the first temples in India to fly the tricolour alongside religious flags on Independence Day and Republic Day — a distinctive, locally-attested history rather than an independently footnoted academic record.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Ranchi Birsa Munda Airport","nearest_airport_distance_km":6.8,"nearest_railway_station_name":"Argora railway station","nearest_railway_distance_km":3.1,"emergency_contact_notes":null,"sthala_purana_source":"Local history and tradition","architecture_style":null,"construction_century":null},{"id":"69492a84-03cf-46f1-b47b-13f63bad6723","name":"Mahabhairav Temple","deity":"Shiva as Mahabhairav","sampradaya":"Shaiva","significance":[],"country":"India","state":"Assam","district":"Sonitpur","town":"Porua Chariali","latitude":26.63417,"longitude":92.79639,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Brahmaputra River","river_distance_km":2.7,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:11.054915+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Shiva temple on a hillock in northern Tezpur. It is said that King Bana built it in stone, and the present concrete building is a renovation. A committee headed by the Deputy Commissioner of Sonitpur manages it. Maha Shivaratri is the main festival, and bhang-laced laddus are offered as prasad.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Tezpur Air Force Station","nearest_airport_distance_km":8.9,"nearest_railway_station_name":"Dekargaon railway station","nearest_railway_distance_km":6.1,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Mahabhairav Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"695ad875-ca93-4e64-99e2-ce6ed2b408e2","name":"Brihadeeswarar Temple, Thanjavur","deity":"Shiva (Brihadeeswarar)","sampradaya":null,"significance":[],"country":"India","state":"Tamil Nadu","district":"Thanjavur","town":"Thanjavur","latitude":10.7828,"longitude":79.1318,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Kaveri","river_distance_km":3,"best_season_notes":"Dec–Mar, early morning to avoid the heat. Like the rest of Tamil Nadu, Thanjavur's rains come from the northeast monsoon in Oct–Nov rather than the June–September window most of India associates with monsoon season.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-11-04T12:15:35.665826+00:00","sthala_purana":"Built by the Chola emperor Raja Raja I and completed around 1010 CE, this is one of India's largest temples and a UNESCO World Heritage Site. Its 66-metre vimana was, for centuries, among the tallest structures in the world, and tradition holds the single 80-tonne granite capstone at its peak was hauled up a 6-kilometre earthen ramp — with some accounts claiming the temple's shadow never falls on the ground at noon, a detail popular in local lore though not something the temple asks visitors to verify.","etiquette_notes":null,"native_name":"பிரகதீஸ்வரர் கோயில்","morning_opens_at":"06:00:00","morning_closes_at":"12:30:00","evening_opens_at":"16:00:00","evening_closes_at":"20:30:00","timings_notes":"Sanctum closed roughly 12:30–4pm daily for rituals.","accessibility_notes":null,"nearest_airport_name":"Thanjavur Air Force Station","nearest_airport_distance_km":7.1,"nearest_railway_station_name":"Thanjavur Junction railway station","nearest_railway_distance_km":1,"emergency_contact_notes":null,"sthala_purana_source":null,"architecture_style":"Dravidian","construction_century":11},{"id":"69b525d0-5261-4d1b-a7ee-ea50fa406520","name":"Kamakshi Amman Temple, Kanchipuram","deity":"Kamakshi (Parvati)","sampradaya":"Shakta","significance":["Shakti Peetha","Sapta Puri"],"country":"India","state":"Tamil Nadu","district":"Kanchipuram","town":"Kanchipuram","latitude":12.8342,"longitude":79.7036,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Temple dining hall — free meals daily","food_source_contact":null,"food_distance_km":0.1,"nearest_river_name":"Vegavathy","river_distance_km":1,"best_season_notes":"Dec–Mar; easy to combine with Ekambareswarar Temple in the same town. As with the rest of Tamil Nadu, Kanchipuram's heaviest rain falls in Oct–Nov via the northeast monsoon, not the summer months.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-09-05T18:43:32.800302+00:00","sthala_purana":"Kamakshi is said to have worshipped Shiva here as a lingam of sand beneath a mango tree, and to have won him by that penance. Adi Shankaracharya is traditionally associated with the establishment of the Sri Chakra in this sanctum.","etiquette_notes":null,"native_name":"காமாக்ஷி அம்மன் கோயில்","morning_opens_at":"06:00:00","morning_closes_at":"12:00:00","evening_opens_at":"16:00:00","evening_closes_at":"20:00:00","timings_notes":"Overall gates open 5:30am–8:30pm; stays open till 9:30pm on Fridays and 10:30pm on Purnima.","accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":190,"nearest_railway_station_name":"Kanchipuram Railway Station","nearest_railway_distance_km":3,"emergency_contact_notes":null,"sthala_purana_source":null,"architecture_style":"Dravidian","construction_century":9},{"id":"6a19f651-d0ca-4a7f-b448-810ee72e2b21","name":"Narapura Venkateswara Temple, Jammalamadugu","deity":"Vishnu as Venkateswara","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Andhra Pradesh","district":"YSR Kadapa","town":"Moragudi","latitude":14.85101,"longitude":78.38368,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Penna River","river_distance_km":0.8,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:54.58588+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"An old Venkateswara temple at Jammalamadugu, Andhra Pradesh, named for the devotee Narapuraiah who built it. The complex includes an Anjaneya shrine, a kalyana mantapam and a goshala. It has been under TTD control since 2008 and is busiest on Saturdays.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kadapa Airport","nearest_airport_distance_km":55.7,"nearest_railway_station_name":"Jammalamadugu railway station","nearest_railway_distance_km":1.6,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Narapura Venkateswara Temple, Jammalamadugu), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"6a27549d-c035-426c-bd33-30c8d18a5ac4","name":"Sri Satyanarayana Swamy Temple, Annavaram","deity":"Satyanarayana Swamy (Vishnu)","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Andhra Pradesh","district":"Kakinada","town":"Annavaram","latitude":17.2833,"longitude":82.2833,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"brahmin_run_kitchen","food_source_name":"Temple annadanam hall — free meals served daily to pilgrims","food_source_contact":null,"food_distance_km":0,"nearest_river_name":"Pampa","river_distance_km":0.3,"best_season_notes":"Every full-moon (Purnima) day draws large crowds for the Satyanarayana Vratam; Kartika Purnima is the busiest of the year.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T13:05:55.016033+00:00","updated_at":"2026-11-04T12:15:35.665826+00:00","sthala_purana":"Set on Ratnagiri hill above the village of Annavaram, the present temple traces to a vision reported by a local benefactor pointing to the deity's self-manifest presence on the hill; construction began in 1891 and the shrine grew over the following decades into one of Andhra Pradesh's most-visited pilgrimage centres, closely associated with the Satyanarayana Vratam described in the Skanda Purana.","etiquette_notes":null,"native_name":"శ్రీ సత్యనారాయణ స్వామి దేవస్థానం","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Rajahmundry Airport","nearest_airport_distance_km":53.9,"nearest_railway_station_name":"Annavaram","nearest_railway_distance_km":2,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition, drawing on the Skanda Purana account of the Satyanarayana Vratam","architecture_style":null,"construction_century":null},{"id":"6a718095-52c4-444f-bf07-14f656850a11","name":"Kalabhairavi Temple","deity":"Chamunda (Kalabhairavi)","sampradaya":"Shakta","significance":[],"country":"India","state":"Odisha","district":"Khordha","town":"Mancheswar","latitude":20.36111,"longitude":85.85472,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Prachi river tributary River","river_distance_km":3.7,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:38.196668+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A shrine within the Jaleswar Siva temple precinct at Kalarahanga, Bhubaneswar. Its image is a four-armed Chamunda seated on a corpse, holding a khatvanga, a snake and a severed head, with a broken lower right hand. She wears a jatamukuta crown and a skull garland, and the image rests on a low pedestal.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_