ised; location via OpenStreetMap","architecture_style":"Kalyana Chalukya","construction_century":null},{"id":"6aba5ac6-0d21-4aaf-a7e2-0224e506c7c9","name":"Dagadusheth Halwai Ganapati Temple","deity":"Ganesha","sampradaya":"Ganapatya","significance":[],"country":"India","state":"Maharashtra","district":"Pune","town":"Pune","latitude":18.51639,"longitude":73.85611,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Mutha River","river_distance_km":0.6,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:47.875457+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Ganesha temple in Pune that draws over a hundred thousand devotees a year, with large crowds during the ten-day Ganeshotsav festival. The main idol is reported to be insured for 10 million rupees. The article notes the festival marked 134 years in 2026.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Pune International Airport","nearest_airport_distance_km":9.7,"nearest_railway_station_name":"Shivajinagar railway station","nearest_railway_distance_km":1.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Dagadusheth Halwai Ganapati Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"6acc0178-baa1-4382-90cc-2e86991a5886","name":"Grishneshwar Jyotirlinga, Ellora","deity":"Shiva (Grishneshwar)","sampradaya":null,"significance":["Jyotirlinga"],"country":"India","state":"Maharashtra","district":"Chhatrapati Sambhajinagar","town":"Ellora","latitude":20.0233,"longitude":75.177,"sandhya_friendly":"un