r reinstated by Krishnappa Nayak. Six daily rituals are held.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Neyveli Airport","nearest_airport_distance_km":29.8,"nearest_railway_station_name":"Chidambaram railway station","nearest_railway_distance_km":1.3,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Govindaraja Perumal Temple), summarised; location via OpenStreetMap","architecture_style":"Dravidian","construction_century":12},{"id":"7eebd13f-66dd-43c2-8a12-8645668ac34a","name":"Chakreshvari Siva Temple","deity":"Shiva (lingam)","sampradaya":"Shaiva","significance":[],"country":"India","state":"Odisha","district":"Khordha","town":"Bhubaneswar Municipal Corporation","latitude":20.24083,"longitude":85.83667,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Dayaa River","river_distance_km":3.2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:38.196668+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A living Shiva temple at Hatiasuni lane, Rajarani Colony, Bhubaneswar, given a date in the 10th to 11th century. The lingam sits in a circular yonipitha, and a tank lies to the west. Shivaratri, Diwali and Sankranti are observed, and the site is used for thread ceremonies, rudrabhisheka and chandrabhisheka.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Biju Patnaik International Airport","nearest_airport_distance_km":2.8,"nearest_railway_sta